def find_minimal_edit(s_in, s_out):
    """Find the minimal edit between two strings"""
    # Simple approach: find first difference and determine what needs to change
    min_len = min(len(s_in), len(s_out))

    # Find first position where they differ
    pos = 0
    while pos < min_len and s_in[pos] == s_out[pos]:
        pos += 1

    # If we've reached the end of one string, it's insertion/deletion
    if pos == min_len:
        if len(s_in) < len(s_out):
            # Insertion at the end
            return ("", s_out[pos:], pos)
        else:
            # Deletion at the end
            return (s_in[pos:], "", pos)

    # Find where the differing part ends
    old_end = pos
    new_end = pos
    while old_end < len(s_in) and new_end < len(s_out) and s_in[old_end] == s_out[new_end]:
        old_end += 1
        new_end += 1

    # Check if it's insertion or deletion
    if old_end == len(s_in) and new_end < len(s_out):
        # Insertion
        return ("", s_out[pos:new_end], pos)
    elif old_end < len(s_in) and new_end == len(s_out):
        # Deletion
        return (s_in[pos:old_end], "", pos)
    else:
        # Substitution/Replacement
        return (s_in[pos:old_end], s_out[pos:new_end], pos)

